                await ContractorPlacementOverdueStatusMap.DeleteInvalidEntriesAsync(db, plcObj.Id);

                var profiles = await plcObj.AllProfilesAsync(db);
                foreach (var p in profiles)
                {
                    if (p.ValidFrom <= p.ValidTo)
                    {
                        plcObj.StartDate = DateSanitize(plcObj.StartDate);
                        if (plcObj.StartDate < p.ValidFrom)
                        {
                            p.ValidFrom = plcObj.StartDate;
                            await p.SaveAsync(db);
                            await Profile.VoidAfterProfileAsync(db, plcObj.Id, p.ValidFrom);
                            break;
