        grp.MapGet("/percentage-lookup", (double increment, double min, double max) =>
        {
            var list = new Dictionary<string, object>();
            var begin = Math.Max(min, 0.0);
            var end = Math.Min(max, 100.0);
            var add = Math.Max(Math.Min(increment, 100.0), 0.01);
            while (begin <= end)
            {
                var key = string.Format("{0:F2}", begin);
                list[key] = new { value = string.Format("{0:F2} %", begin) };
                begin += add;
            }
            return Results.Json(list);
        });

