        // Contractor_placement.php L504-575 → bestMatch
        // Model/Contractor_placement.php L504-575 → MapGet
        grp.MapGet("/best-match", async (
            [FromQuery] List<string> custids,
            [FromQuery] string contractorname,
            [FromQuery] string tsweek,
            SqlConnection dbConnection) =>
        {
            var list = new List<dynamic>();
            var quotedCustIds = QuoteAndTransform(custids);
            var contractors = QuoteAndTransform(await ContractorBestMatch(contractorname, dbConnection));

            if (!quotedCustIds.Any() || !contractors.Any())
            {
                return Results.Json(list);
            }

            var query = @"SELECT cp.id AS id,
                                cp.start_date AS start_date,
                                cp.deactivation_date AS deactivation_date,
                                cp.is_active AS is_active,
                                c.id AS contractor_id,
                                c.firstname AS firstname,
                                c.mi AS mi,
                                c.lastname AS lastname,
                                c.is_active AS is_active_contractor
                         FROM contractor_placement cp
                         JOIN contractor c ON cp.contractor_id = c.id
                         WHERE cp.customer_id IN (@CustIds)
                           AND c.id IN (@Contractors)";

            var parameters = new { CustIds = quotedCustIds, Contractors = contractors };
            list = (await dbConnection.QueryAsync<dynamic>(query, parameters)).ToList();

            if (!list.Any())
            {
                query = @"SELECT cp.id AS id,
                                cp.start_date AS start_date,
                                cp.deactivation_date AS deactivation_date,
                                cp.is_active AS is_active,
                                c.id AS contractor_id,
                                c.firstname AS firstname,
                                c.mi AS mi,
                                c.lastname AS lastname,
                                c.is_active AS is_active_contractor
                         FROM contractor_placement cp
                         JOIN contractor c ON cp.contractor_id = c.id
                         WHERE c.id IN (@Contractors)";

                list = (await dbConnection.QueryAsync<dynamic>(query, new { Contractors = contractors })).ToList();
            }

            if (list.Count > 1)
            {
                var tssecs = DateTimeOffset.Parse(tsweek).ToUnixTimeSeconds();
                var maxdeviation = 7 * 86400;
                list = list.Aggregate(new List<dynamic>(), (carry, entry) =>
                {
                    var startDate = DateTimeOffset.Parse(entry.start_date).ToUnixTimeSeconds();
                    var deactivationDate = entry.deactivation_date != "2000-01-01 00:00:00" ? DateTimeOffset.Parse(entry.deactivation_date).ToUnixTimeSeconds() : long.MaxValue;

                    if (!ContractorPlacementIsPerm(entry.id) &&
                        (tssecs - startDate >= -maxdeviation) &&
                        (tssecs - deactivationDate <= maxdeviation))
                    {
                        carry.Add(entry);
                    }
                    return carry;
                });
            }

            return Results.Json(list);
        });

