            if (cp == null)
            {
                Console.WriteLine("  Placement not populated");
                return Results.NotFound("Placement not populated");
            }

            var contractor = await db.Contractors.FindAsync(cp.ContractorId);
            if (contractor == null || contractor.Id < 2)
            {
                Console.WriteLine("  Contractor not populated");
                return Results.NotFound("Contractor not populated");
            }

            jobreqId ??= cp.JobreqId;
            if (jobreqId < 2)
            {
                Console.WriteLine("  Job not populated");
                return Results.NotFound("Job not populated");
            }

            var candidates = await db.CandidateActivities
                .Where(ca => ca.JobreqId == jobreqId)
                .Select(ca => ca.CandidateId)
                .Distinct()
                .ToListAsync();

            foreach (var candidateId in candidates)
            {
                var candidate = await db.Candidates.FindAsync(candidateId);
                if (candidate != null && candidate.Email == contractor.Email)
                {
                    return Results.Ok(candidate);
                }
            }

            Console.WriteLine($"  {contractor.Firstname} {contractor.Lastname}");
            foreach (var candidateId in candidates)
            {
                var candidate = await db.Candidates.FindAsync(candidateId);
                if (candidate != null)
                {
                    Console.WriteLine($"  * {candidate.Firstname} {candidate.Lastname}");
                    if (candidate.Firstname == contractor.Firstname && candidate.Lastname == contractor.Lastname)
                    {
                        return Results.Ok(candidate);
                    }
                }
            }

            return Results.NotFound();
        });

