                       v.name AS vendor_name
                  FROM contractor_placement cp
                  JOIN profile p ON p.contractor_placement_id = cp.id
                  JOIN vendor v ON cp.vendor_id = v.id
                 WHERE cp.is_active = 'Y'
                   AND p.id = recentProfile(cp.id)
                   AND p.employment_type_id = 2
                   AND cp.is_pending = 'N'
                   AND cp.customer_id NOT IN @ExcludeOMSCustomers
                   AND cp.id NOT IN (38413)
                   AND (
                       EXISTS (SELECT 1 FROM vendormaster_vendor_map WHERE vendor_id = v.id AND vendormaster_id = 1)
                       OR
                       NOT EXISTS (SELECT 1 FROM vendormaster_vendor_map WHERE vendor_id = v.id)
                   )";

            var rows = await dbConnection.QueryAsync(query, new { ExcludeOMSCustomers = excludeOMSCustomers });
            var site = config.GetValue<string>("App:site") ?? "";
            var envEntry = Environment.GetEnvironmentVariable("env_entry") ?? "";
            var msg = new StringBuilder();
            msg.AppendLine("<table border='1'><thead><tr><th>Placement ID</th><th>Placement Name</th><th>Vendor Name</th></tr>");
            int rowCount = 0;

            foreach (var row in rows)
            {
                var placementId = row.id;
                var name = row.name;
                var vendorName = row.vendor_name;
                msg.AppendLine($"<tr><td><a href='{site}{envEntry}/entity/contractor_placement/{placementId}'>{placementId}<a/></td><td>{name}</td><td>{vendorName}</td></tr>");
                rowCount++;
            }

            msg.AppendLine("</thead></table>");

            if (rowCount > 0)
            {
                var subject = "Active C2C Placements with Unassigned Vendors";
                var to = config.GetValue<string>("unassigned vendors list")?.Split(',') ?? Array.Empty<string>();
                await MsgoutQueue(to, subject, msg.ToString(), cc);
            }

            return Results.Ok(new { rows = rowCount });
        });

        return app;
    }

