                countryId = await Country.AddAsync(country, db);
            }

            var query = @"SELECT a.id FROM address a
                          JOIN address_type at ON a.address_type_id = at.id
                          WHERE a.obj_id = @objId AND a.st1 = @st1 AND a.st2 = @st2
                          AND a.city = @city AND a.state = @state AND a.zip = @zip
                          AND a.country_id = @countryId AND at.name = @type";

            var parameters = new[]
            {
                new SqlParameter("@objId", objId),
                new SqlParameter("@st1", st1),
